func (t HealthType) ValueFromObject(ctx context.Context, in basetypes.ObjectValue) (basetypes.ObjectValuable, diag.Diagnostics) {
	var diags diag.Diagnostics

	attributes := in.Attributes()

	failCountAttribute, ok := attributes["fail_count"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`fail_count is missing from object`)

		return nil, diags
	}

	failCountVal, ok := failCountAttribute.(basetypes.Int64Value)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`fail_count expected to be basetypes.Int64Value, was: %T`, failCountAttribute))
	}

	statusAttribute, ok := attributes["status"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`status is missing from object`)

		return nil, diags
	}

	statusVal, ok := statusAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`status expected to be basetypes.StringValue, was: %T`, statusAttribute))
	}

	if diags.HasError() {
		return nil, diags
	}

	return HealthValue{
		FailCount: failCountVal,
		Status:    statusVal,
		state:     attr.ValueStateKnown,
	}, diags
}

