func NewHealthValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (HealthValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing HealthValue Attribute Value",
				"While creating a HealthValue value, a missing attribute value was detected. "+
					"A HealthValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("HealthValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid HealthValue Attribute Type",
				"While creating a HealthValue value, an invalid attribute value was detected. "+
					"A HealthValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("HealthValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("HealthValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra HealthValue Attribute Value",
				"While creating a HealthValue value, an extra attribute value was detected. "+
					"A HealthValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra HealthValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewHealthValueUnknown(), diags
	}

	failCountAttribute, ok := attributes["fail_count"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`fail_count is missing from object`)

		return NewHealthValueUnknown(), diags
	}

	failCountVal, ok := failCountAttribute.(basetypes.Int64Value)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`fail_count expected to be basetypes.Int64Value, was: %T`, failCountAttribute))
	}

	statusAttribute, ok := attributes["status"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`status is missing from object`)

		return NewHealthValueUnknown(), diags
	}

	statusVal, ok := statusAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`status expected to be basetypes.StringValue, was: %T`, statusAttribute))
	}

	if diags.HasError() {
		return NewHealthValueUnknown(), diags
	}

	return HealthValue{
		FailCount: failCountVal,
		Status:    statusVal,
		state:     attr.ValueStateKnown,
	}, diags
}

func NewHealthValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) HealthValue {
	object, diags := NewHealthValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewHealthValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t HealthType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewHealthValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewHealthValueUnknown(), nil
	}

	if in.IsNull() {
		return NewHealthValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewHealthValueMust(HealthValue{}.AttributeTypes(ctx), attributes), nil
}

